{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data/explore.csv')
exposures = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
# within-region correlation
for e in exposures:
    cs=[]
    for r,g in df.groupby('region'):
        cs.append(g[[e,'species_richness']].dropna().corr().iloc[0,1])
    print(f"{e:15s} within-region corr: {np.round(cs,3)}")
"}
